let s2={done:false};
const lessons2=[{n:3,g:4,icon:'🍪',box:'봉지',unit:'개',name:'함께 해 보기',steps:['recall','build','slots','explore','first','second']},{n:2,g:3,icon:'🍪',box:'봉지',unit:'개',name:'그림 → 덧셈식',steps:['add']},{n:4,g:3,icon:'🍪',box:'봉지',unit:'개',name:'덧셈식 → 곱셈식',steps:['mul']},{n:3,g:4,icon:'🍪',box:'봉지',unit:'개',name:'곱셈식 → 그림',steps:['picture']},{n:5,g:3,icon:'✏️',box:'통',unit:'자루',name:'생활 속 연결',steps:['add','mul','first','second']},{n:2,g:4,icon:'🍪',box:'봉지',unit:'개',name:'혼자 확인 1',test:true,steps:['add','mul','first','second']},{n:4,g:3,icon:'🌷',box:'꽃다발',unit:'송이',name:'혼자 확인 2',test:true,steps:['add','mul','first','second']},{n:5,g:2,icon:'✏️',box:'통',unit:'자루',name:'혼자 확인 3',test:true,steps:['add','mul','first','second']}];
function start2(){s2={done:s2.done,index:0,step:0,taps:0,slots:[],focus:'',seen:[],score:0,clean:true,retry:false,recheck:false,passed:false,msg:'1단계에서 만난 간식 그림이에요. 3개씩 4묶음, 모두 12개를 살펴봐요.'};render2()}
const d2=()=>lessons2[s2.index];const mode2=()=>d2().steps[s2.step];const add2=(n,g)=>Array(g).fill(n).join(' + ');
function groups2(n,g,icon,box,interactive=false){return `<div class="bags">${Array.from({length:g},(_,i)=>`<div class="bag ${s2.focus==='one'&&i===0||s2.focus==='all'?'highlight':''} ${interactive&&i<s2.taps?'counted':''}"><span class="baglabel">${box} ${i+1}</span><div class="items" aria-label="${n}개">${Array(n).fill(`<span aria-hidden="true">${icon}</span>`).join('')}</div>${interactive?`<button onclick="tap2()" ${i!==s2.taps?'disabled':''}>${i<s2.taps?'✓ 식에 붙였어요':'식에 붙이기'}</button>`:''}</div>`).join('')}</div>`}
function tap2(){s2.taps++;s2.msg='한 묶음마다 같은 수가 한 번씩 더 쓰여요.';render2()}
function focus2(part){s2.focus=part;if(!s2.seen.includes(part))s2.seen.push(part);s2.msg=part==='one'?`앞의 ${d2().n}: 한 묶음 안의 ${d2().n}${d2().unit}을 가리켜요.`:`뒤의 ${d2().g}: 전체 ${d2().g}묶음을 가리켜요.`;render2()}
function slot2(n){if(s2.slots.length<2)s2.slots.push(n);render2()}
function choose2(ok){if(s2.passed)return;if(!ok){s2.clean=false;s2.retry=true;s2.focus=mode2()==='second'?'all':'one';s2.msg=mode2()==='picture'?'앞의 수는 한 묶음 안의 개수, 뒤의 수는 묶음의 수예요. 그림을 다시 살펴봐요.':`한 ${d2().box}에는 ${d2().n}${d2().unit}씩 있어요. 그 수가 ${d2().g}번 더해져요. 그림을 보고 다시 골라 봐요.`;if(mode2()==='slots')s2.slots=[];render2();return}if(s2.retry){s2.retry=false;s2.recheck=true;s2.slots=[];s2.focus='';s2.msg='잘 고쳤어요! 이제 힌트를 가렸어요. 같은 연결을 한 번 더 해 봐요.';render2();return}s2.passed=true;s2.focus='';s2.msg=s2.recheck?'힌트 없이도 연결했어요!':'그림과 식이 잘 연결되었어요!';render2()}
function next2(){s2.step++;s2.taps=0;s2.slots=[];s2.focus='';s2.seen=[];s2.retry=false;s2.recheck=false;s2.passed=false;if(s2.step>=d2().steps.length){if(d2().test&&s2.clean)s2.score++;s2.index++;s2.step=0;s2.clean=true}if(s2.index===lessons2.length){bridge2();return}s2.msg='그림 속에서 수가 뜻하는 것을 찾아봐요.';render2();document.querySelector('#app').scrollIntoView?.({block:'start'})}
function render2(){view='stage2';const d=d2(),m=mode2();const title={recall:'3개씩 4묶음, 모두 12개예요.',build:'봉지를 하나씩 눌러 덧셈식을 만들어요.',slots:`${d.n}이 ${d.g}번 더해졌어요. 곱셈식으로 써 볼까요?`,explore:'식의 두 수를 하나씩 눌러 보세요.',add:'그림에 맞는 덧셈식을 골라요.',mul:'덧셈식을 곱셈식으로 바꾸어요.',picture:'3 × 4에 맞는 그림을 골라요.',first:`앞의 ${d.n}은 무엇을 가리킬까요?`,second:`뒤의 ${d.g}는 무엇을 가리킬까요?`}[m];let body='';if(m==='picture'){body=`<div class="picture-options">${[[3,4],[4,3]].map(([n,g],i)=>`<div class="picture-option">${groups2(n,g,d.icon,d.box)}<button class="primary" onclick="choose2(${i===0})" ${s2.passed?'disabled':''}>${n}개씩 ${g}묶음 그림</button></div>`).join('')}</div>`}else{if(m!=='mul')body=groups2(d.n,d.g,d.icon,d.box,m==='build');if(m==='build')body+=`<div class="equation" aria-live="polite">${s2.taps?add2(d.n,s2.taps):'봉지를 눌러 시작해요'}${s2.taps===d.g?' = '+d.n*d.g:''}</div>`;if(m==='slots')body+=`<div class="equation">${add2(d.n,d.g)} = ${d.n*d.g}</div><div class="equation">${s2.slots[0]??'□'} × ${s2.slots[1]??'□'} = ${d.n*d.g}</div><div class="choices">${[2,3,4,5].map(n=>`<button onclick="slot2(${n})" ${s2.slots.length===2||s2.passed?'disabled':''}>${n}</button>`).join('')}<button onclick="s2.slots=[];render2()" ${s2.passed?'disabled':''}>다시 놓기</button><button onclick="choose2(s2.slots[0]===d2().n&&s2.slots[1]===d2().g)" ${s2.slots.length!==2||s2.passed?'disabled':''}>식 확인</button></div>`;if(m==='explore')body+=`<div class="equation"><button onclick="focus2('one')" aria-label="앞의 수 ${d.n}">${d.n}</button> × <button onclick="focus2('all')" aria-label="뒤의 수 ${d.g}">${d.g}</button> = ${d.n*d.g}</div>`;if(m==='add'||m==='mul'){if(m==='mul')body+=`<div class="equation">${add2(d.n,d.g)} = ${d.n*d.g}</div>${s2.focus?groups2(d.n,d.g,d.icon,d.box):''}`;const correct=m==='add'?add2(d.n,d.g):`${d.n} × ${d.g}`;const wrong=m==='add'?add2(d.g,d.n):`${d.g} × ${d.n}`;body+=`<div class="choices">${(s2.index%2?[wrong,correct]:[correct,wrong]).map(v=>`<button onclick="choose2(${v===correct})" ${s2.passed?'disabled':''}>${v} = ${d.n*d.g}</button>`).join('')}</div><p class="small">지금은 그림의 ‘몇 개씩, 몇 묶음’ 순서와 연결해요.</p>`}if(m==='first'||m==='second')body+=`<div class="equation"><span class="${m==='first'?'number-focus':''}">${d.n}</span> × <span class="${m==='second'?'number-focus':''}">${d.g}</span> = ${d.n*d.g}</div><div class="choices"><button onclick="choose2(${m==='first'})" ${s2.passed?'disabled':''}>한 묶음 안의 개수</button><button onclick="choose2(${m==='second'})" ${s2.passed?'disabled':''}>묶음의 수</button></div>`}const ready=s2.passed||m==='recall'||m==='build'&&s2.taps===d.g||m==='explore'&&s2.seen.length===2;app.innerHTML=`<div class="topline"><span class="pill">2단계 · 간식 봉지에 식 붙이기</span><span class="small">활동 ${s2.index+1} / 8</span></div><section class="activity"><div class="track">${lessons2.map((_,i)=>`<i class="${i<=s2.index?'done':''}"></i>`).join('')}</div><span class="small">${d.name}</span><h1 class="instruction">${title}</h1>${s2.index===4?'<p>연필이 5자루씩 들어 있는 통이 3개 있어요.</p>':''}<div class="workspace">${body}</div><div class="feedback ${s2.passed?'good':''}" role="status">${s2.msg}</div><div class="actions"><button onclick="home()">전체 단계</button><button class="primary" onclick="next2()" ${ready?'':'disabled'}>다음으로 →</button></div></section>`}
function bridge2(){view='stage2';s2.done=s2.score>=2;app.innerHTML=`<section class="activity"><span class="pill">2단계 마무리 · 다음 발견</span><h1>${s2.done?'그림에 식을 붙일 수 있어요!':'그림과 식을 연결해 봤어요!'}</h1><p>세 가지 확인 그림 중 ${s2.score}개에서 덧셈식·곱셈식과 두 수의 뜻을 도움 없이 연결했어요.${s2.done?' 다음 단계로 나아갈 준비가 되었어요.':' 다시 연습하며 연결을 익혀 봐요.'}</p><div class="workspace">${groups2(3,4,'🍪','봉지')}<div class="equation">3 + 3 + 3 + 3</div><h2>3개가 든 봉지를 한 개 더 놓으면<br>무엇이 더해질까요?</h2><div class="choices"><button onclick="bridgeAnswer2(4)">4를 더해요</button><button onclick="bridgeAnswer2(3)">3을 더해요</button></div><div id="bridgeResult" role="status"></div></div><p class="small">3단계에서는 한 묶음씩 늘려 단을 만들어요. 3단계에서 한 묶음씩 늘려 보세요.</p><div class="actions"><button class="primary" onclick="start3()">3단계로 가기</button><button onclick="start2()">2단계 다시 하기</button><button class="primary" onclick="home()">전체 단계 보기</button></div></section>`}
function bridgeAnswer2(n){document.querySelector('#bridgeResult').innerHTML=n===3?`${groups2(3,5,'🍪','봉지')}<p class="feedback good">맞아요! 3개짜리 한 묶음이 더 생겨요.<br>3 + 3 + 3 + 3 + 3 = 15</p>`:'<p class="feedback">새 봉지 하나 안에 간식이 몇 개 있나요? 한 묶음의 개수를 더해 봐요.</p>'}
